function text(cp) {
  return cp.split(' ').map(function (h) { return String.fromCodePoint(parseInt(h, 16)); }).join('');
}

function diff(row, out, want) {
  return row[0] + ': ' + JSON.stringify(out) + ' (expected ' + JSON.stringify(want) + ')';
}

describe('@rhinostone/swig-django — pluralize reads a string count as Python\'s float() does, checked against Django 5.2.18', function () {

  it('on the sync render path', function () {
    var diffs = [];
    expect(rows.length).to.be.greaterThan(0);
    rows.forEach(function (row) {
      var out = new Engine({ cache: false }).compile(row[1])({ s: text(row[2]) });
      if (out !== row[3]) { diffs.push(diff(row, out, row[3])); }
    });
    expect(diffs).to.eql([]);
  });

  it('on the async render path', function (done) {
    var templates = {}, inst, diffs = [], i = 0;
    rows.forEach(function (row) { templates['/' + row[0]] = row[1]; });
    inst = new Engine({ loader: {
      async: true,
      resolve: function (to) { return to; },
      load: function (id, cb) {
        if (cb) { setImmediate(function () { cb(null, templates[id]); }); return undefined; }
        return templates[id];
      }
    } });
    function next() {
      var row = rows[i];
      if (!row) {
        try { expect(diffs).to.eql([]); } catch (e) { return done(e); }
        return done();
      }
      i += 1;
      inst.renderFile('/' + row[0], { s: text(row[2]) }, function (err, out) {
        out = err ? 'THROW ' + err.message : out;
        if (out !== row[3]) { diffs.push(diff(row, out, row[3])); }
        next();
      });
    }
    next();
  });

  it('reads a long run of whitespace inside the count in linear time', function () {
    var run = new Array(100001).join(' '), wide = new Array(100001).join(String.fromCodePoint(0x3000)), start = Date.now();
    expect(filters.pluralize('1' + run + 'x', 'y,ies')).to.equal('');
    expect(filters.pluralize('x' + run + '1', 'y,ies')).to.equal('');
    expect(filters.pluralize('1' + wide + 'x', 'y,ies')).to.equal('');
    expect(filters.pluralize(run + '1' + wide, 'y,ies')).to.equal('y');
    expect(Date.now() - start).to.be.lessThan(500);
  });

  describe('an engine without Unicode property escapes', function () {
    var fallback, refusals = 0;

    // Load a second copy of the filters while RegExp refuses `\p{...}`, as an
    // engine without ES2018 property escapes does; RegExp and the module
    // cache are put back whatever happens.
    before(function () {
      var file = require.resolve('@rhinostone/swig-django/lib/filters'),
        cached = require.cache[file],
        Real = RegExp;
      function NoPropertyEscapes(src, flags) {
        if (String(src).indexOf('\\p{') !== -1) {
          refusals += 1;
          throw new SyntaxError('Invalid escape');
        }
        return new Real(src, flags);
      }
      NoPropertyEscapes.prototype = Real.prototype;
      delete require.cache[file];
      global.RegExp = NoPropertyEscapes;
      try {
        fallback = require(file);
      } finally {
        global.RegExp = Real;
        require.cache[file] = cached;
      }
    });

    it('reads Python\'s whitespace and ASCII digits, and no other decimal digit', function () {
      var diffs = [];
      expect(refusals).to.be.greaterThan(0);
      expect(fallback).not.to.be(filters);
      rows.forEach(function (row) {
        var out;
        if (row[4] === null) { return; }
        out = fallback.pluralize(text(row[2]), 'y,ies');
        if (out !== row[4]) { diffs.push(diff(row, out, row[4])); }
      });
      expect(diffs).to.eql([]);
    });
  });
});
